-- ==========================================================
-- Catálogo de Categorías y Alimentos (AFT API)
-- Total Categorías: 8 | Total Alimentos: 664
-- ==========================================================

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `foods`;
DROP TABLE IF EXISTS `food_categories`;

CREATE TABLE `food_categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `food_categories_name_unique` (`name`),
  UNIQUE KEY `food_categories_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `foods` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `food_category_id` bigint unsigned NOT NULL,
  `subcategory` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `state` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `portion_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '100 g',
  `portion_detail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `base_quantity` decimal(8,2) NOT NULL DEFAULT '100.00',
  `base_unit` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'g',
  `gram_weight` decimal(8,2) DEFAULT NULL,
  `calories` decimal(8,2) NOT NULL DEFAULT '0.00',
  `protein` decimal(8,2) NOT NULL DEFAULT '0.00',
  `carbs` decimal(8,2) NOT NULL DEFAULT '0.00',
  `fat` decimal(8,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `foods_food_category_id_name_index` (`food_category_id`,`name`),
  KEY `foods_name_index` (`name`),
  CONSTRAINT `foods_food_category_id_foreign` FOREIGN KEY (`food_category_id`) REFERENCES `food_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;









SET FOREIGN_KEY_CHECKS = 1;
